import {mountStory} from './focus-story.mjs';
import {mountSupport} from './focus-support.mjs';
import {arrangeCase} from './focus-case-design.mjs';
import {mountExperience} from './focus-experience.mjs';
import {mountNewCase} from './focus-new-case.mjs';
import {createApi,loadSnapshot,sourcesUnavailable,validateCase} from './focus-api.mjs';
import {sourceStatus} from './focus-status.mjs';
import {mountGuide} from './focus-guide.mjs';
import {workspaceView,navigation,accessJourney} from './focus-workspace.mjs';
import {COURSE,crew,createCase,simulatePayment,investigate,rehearse,approve,applyRepair,verify,checks,findings,evidenceSnapshot} from './core.mjs';
import {seedPortfolio,diagnose,customerDraft,recoveryReceipt,proofIsCurrent} from './operations.mjs';
import {queueFor,nextStep,caseLabel} from './focus-model.mjs';
const root=document.querySelector('#focus-app'),backend=window.COURSELATCH_RUNTIME?.backend===true;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cases=[],selected=null,queue='attention',search='',busy=false,error='',consent=false,loaded=false;
let screen='cases',sort='oldest',guided=false; try{guided=sessionStorage.getItem('paytrace-guided')==='true'}catch{} function setGuided(value){guided=value;try{sessionStorage.setItem('paytrace-guided',String(value))}catch{}render();}
const storageKey='paytrace-focus-v1';
const drafts=new Map();
function draftFor(s){const fresh=customerDraft(s),old=drafts.get(s.id);if(old?.evidenceFingerprint===fresh.evidenceFingerprint&&old.kind===fresh.kind)return old;drafts.set(s.id,fresh);return fresh;}
const api=createApi(); let syncRequired=false;
function save(){if(!backend)try{sessionStorage.setItem(storageKey,JSON.stringify(cases))}catch{}}
function merge(s){const i=cases.findIndex(x=>x.id===s.id);if(i<0)cases.push(s);else cases[i]=s;selected=s.id;}
function current(){return cases.find(s=>s.id===selected)}
function notify(message){const n=document.querySelector('#notice');n.textContent=message;n.className='show';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.className='',4500);}
async function refresh(){if(backend){const snapshot=await loadSnapshot(api,selected);cases=snapshot.cases;if(snapshot.state)merge(snapshot.state);}syncRequired=false;save();}
const btn=(action,text,primary=false,disabled=false)=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${busy||disabled||(syncRequired&&['investigate','rehearse','approve','repair','verify','pay'].includes(action))?'disabled':''}>${busy?'Working…':esc(text)}</button>`;
function mode(){return `<div class="mode">${backend?'Server demo · sample merchant':'Interactive demo · sample records · no real payments'}</div>`;}
function dashboard(){return workspaceView({cases,queue,search,sort,backend,busy,screen});}
function review(){const s=current(),d=diagnose(s),done=proofIsCurrent(s)&&!syncRequired&&!sourcesUnavailable(s),[action,label]=sourcesUnavailable(s)?['refresh','Retry source checks']:nextStep(s),stage=done?3:['approved','verifying','unverified','verify-only'].includes(s.phase)?3:s.phase==='rehearsed'?2:s.phase==='investigated'?1:0;
return `<div class="review-shell"><button class="back" data-action="back" ${busy?'disabled':''}>← All cases</button>${mode()}<div class="stepper" aria-label="Case progress">${['Evidence','Preview','Approval','Verification'].map((x,i)=>`<span class="${i===stage?'active':''}"><i>${i<stage||done?'✓':i+1}</i>${x}</span>`).join('')}</div><article class="sheet"><div class="sheet-head"><div class="case-meta"><span class="eyebrow">${esc(s.id)} / ${esc(s.customerName)}’S PURCHASE</span><span class="badge ${done?'good':''}">${syncRequired||sourcesUnavailable(s)?'Current status unconfirmed':esc(caseLabel(s))}</span></div><h1>${done?'A checked outcome. A customer back in.':syncRequired||sourcesUnavailable(s)?'Current case information needs a refresh.':s.writes?'Access updated. Let’s verify it.':s.capture?.status!=='COMPLETED'?'Let’s confirm the payment first.':d.code==='missing_enrollment'?'The payment is complete. Access is missing.':'The purchase needs a closer look.'}</h1><p>${done?'Payment, purchased entitlement, and the lesson-access check agree.':esc(d.next)}</p><div class="purchase"><div class="payment"><img src="assets/paypal-mark.svg" alt="PayPal"><div><strong>$128.00 USD</strong><small>${s.capture?.status==='COMPLETED'?'Payment completed':'Payment not confirmed'} · ${s.capture?.source==='paypal-sandbox'?'Sandbox':s.intakeMode==='sandbox'?'Awaiting sandbox checkout':'Sample record'}</small></div></div><div><strong>${esc(COURSE.name)}</strong><small>${esc(s.order.userId)} · ${esc(s.order.id)}</small></div></div></div><div class="sheet-body">${sourceStatus(s,{backend,uncertain:syncRequired})}${accessJourney(s)}<div class="summary"><div class="eyebrow">${done?'VERIFIED OUTCOME':s.review?'RECOMMENDED NEXT STEP':'START WITH THE EVIDENCE'}</div><h2>${esc(label)}</h2><p>${s.job?.pending?'A server workflow is still running. Refresh its status before continuing.':done?'The case is resolved. The receipt records the approved change and verification result.':s.review?esc(s.review.proposal):'Match the payment to this purchase, inspect current access, and ask the specialists to review the safest next step.'}</p>${s.review?`<p><strong>What we don’t know:</strong> ${esc(s.review.unknown)}</p>`:''}</div>${s.rehearsal?`<h3>The exact correction</h3><div class="diff"><div><small>BEFORE</small><strong>${s.rehearsal.before.active?'Access active':'Course locked'}</strong><p>${esc(s.order.userId)}<br>${esc(COURSE.name)}</p></div><div><small>${s.writes?'APPLIED CHANGE':'PREVIEW · NOT YET APPLIED'}</small><strong>Purchased access active</strong><p>Same customer. Same course.<br>Existing payment unchanged.</p></div></div><p class="footnote">${s.writes?'The grant was applied once. Verification is a separate check.':'This preview does not change customer access. No charge, refund, or account transfer.'}</p>`:''}${s.proof?`<h3>Outcome checks</h3>${s.proof.checks.map(c=>row(c)).join('')}<p class="footnote">${esc(s.proof.transport)} · ${esc(new Date(s.proof.at).toLocaleString())}</p>`:''}<details class="detail"><summary>Purchase evidence <small>Payment, order & current access</small></summary>${(s.evidenceAvailable===false?[{ok:false,label:'Payment evidence unavailable',detail:'A current record is required before a repair can be approved.'}]:checks(s)).map(c=>row(c)).join('')}<details><summary style="margin-top:15px">Inspect source records</summary><pre>${esc(JSON.stringify(evidenceSnapshot(s),null,2))}</pre></details></details><details class="detail"><summary>Specialist review <small>${s.review?(s.review.mode==='scripted'?'Scripted demo consultation':'Evidence consultation'):'Available after investigation'}</small></summary>${s.review?findings(s).map(f=>`<div class="agent"><strong>${esc(crew[f.agent].name)} · ${esc(crew[f.agent].role)}</strong><p>${esc(f.summary)}</p><small>Sources: ${esc(f.sources.join(', '))} · Limitation: ${esc(f.unknown)}</small></div>`).join('')+s.review.exchange.map(e=>`<div class="agent"><strong>${esc(crew[e.agent]?.name||'Reviewer')} · ${esc(e.kind)}</strong><p>${esc(e.summary)}</p><small>Sources: ${esc(e.sources.join(', '))}</small></div>`).join(''):'<p>Run the evidence review to see each specialist’s recommendation and supporting records.</p>'}</details><details class="detail"><summary>Recovery timeline <small>${s.events.length} recorded events</small></summary><ol class="timeline">${s.events.map(e=>`<li><time>${esc(new Date(e.at).toLocaleTimeString())}</time>${esc(e.what)}</li>`).join('')}</ol><p class="footnote">Access writes: ${s.writes} · Verification attempts: ${s.reads}</p></details><details class="detail"><summary>Customer reply <small>Review and copy · never sent automatically</small></summary><textarea aria-label="Customer reply">${esc(draftFor(s).text)}</textarea>${btn('copy','Copy reply')}</details>${s.phase==='rehearsed'?`<label class="consent"><input id="consent" type="checkbox" ${consent?'checked':''} ${busy?'disabled':''}><span>I approve one access grant for <strong>${esc(s.customerName)}</strong>, for <strong>${esc(COURSE.name)}</strong>, using purchase <strong>${esc(s.order.id)}</strong>.</span></label>`:''}</div><div class="actionbar"><p>${s.phase==='rehearsed'?'Approval is tied to this exact preview. Changed evidence requires a new review.':s.phase==='approved'?'Approval recorded. Apply the correction when you’re ready.':done?'Only a successful verification closes the case.':'You stay in control. Every correction requires your approval.'}</p>${btn(action,label,true,s.phase==='rehearsed'&&!consent)}</div></article><p class="footnote">${backend?'Server-backed demo. Production identity and external integrations require configuration.':'Simulation: scripted agents and sample records. No real customer access or payment is changed.'}</p></div>`;}
function row(c){return `<div class="evidence-row"><span class="mark ${c.ok?'':'fail'}">${c.ok?'✓':'!'}</span><div><strong>${esc(c.label)}</strong>${c.detail?`<p>${esc(c.detail)}</p>`:''}</div></div>`;}
function render(){document.querySelector('#workspace-navigation').innerHTML=navigation(selected?'cases':screen);document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{if(busy)return;screen=b.dataset.screen;selected=null;consent=false;error='';render();});root.setAttribute('aria-busy',String(busy));root.innerHTML=`${error||syncRequired?`<div role="alert" class="error"><strong>${esc(error||'Refresh the latest status before continuing.')}</strong><span>Shown information may be out of date. Refresh status before another action; an interrupted request may have completed on the server.</span>${loaded?btn('refresh','Refresh status safely'):''}</div>`:''}${busy&&loaded?'<div class="request-pending" role="status">Retrieving the latest case information. Please wait…</div>':''}${!loaded?`<div class="empty"><h2>${error?'Workspace unavailable':'Loading workspace…'}</h2>${error?btn('reload','Retry loading'):''}</div>`:selected&&current()?review():dashboard()}`;mountExperience(root,selected?current():null,{backend,uncertain:syncRequired||sourcesUnavailable(current()),api});arrangeCase(root,selected?current():null);mountStory(root,selected?current():null,{backend});mountSupport(root,selected?current():null,{backend,onSelect:caseId=>run('select-case',{caseId})});root.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{if(busy)return;screen=b.dataset.screen;selected=null;consent=false;render();});root.querySelector('[aria-label="Sort cases"]')?.addEventListener('change',e=>{sort=e.target.value;render();});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>run(b.dataset.action));root.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>run('select-case',{caseId:b.dataset.case}));root.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{queue=b.dataset.queue;render()});root.querySelector('textarea[aria-label="Customer reply"]')?.addEventListener('input',e=>{const s=current();drafts.set(s.id,{...draftFor(s),text:e.target.value});});root.querySelector('#consent')?.addEventListener('change',e=>{consent=e.target.checked;root.querySelector('[data-action="approve"]').disabled=!consent||busy||syncRequired;});root.querySelector('.search')?.addEventListener('input',e=>{search=e.target.value;const position=e.target.selectionStart;render();const input=root.querySelector('.search');input.focus();try{input.setSelectionRange(position,position)}catch{}});if(loaded)mountGuide({root,state:current(),guided,busy,setGuided,uncertain:syncRequired});}
async function run(action,data={}){if(busy)return;if(syncRequired&&['investigate','rehearse','approve','repair','verify','pay'].includes(action))return;if(action==='new-case'){document.querySelector('.case-create-toolbar button').click();return;}if(action==='checkout'){location.href='recover.html';return;}if(action==='clear-search'){search='';render();return;}if(action==='back'){screen='cases';selected=null;consent=false;error='';render();return;}if(action==='reload')return init();if(action==='copy'){try{await navigator.clipboard.writeText(root.querySelector('textarea[aria-label="Customer reply"]').value);notify('Reply copied. Nothing was sent.');}catch{notify('Select the reply text and copy it manually.');}return;}const s=current();if(action==='approve'&&!consent)return;if(action==='receipt'){const url=URL.createObjectURL(new Blob([JSON.stringify(recoveryReceipt(s,{mode:backend?'server-demo':'browser-simulation'}),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=s.id+'-recovery.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
busy=true;error='';render();try{if(action==='refresh'){await refresh();notify('Records refreshed. No correction applied.');}else if(backend){const result=await api('action',{action,caseId:s?.id,...data,planId:s?.rehearsal?.id});merge(validateCase(result.state));if(result.job)notify('Workflow started. Refresh to check its result.');await refresh();}else if(action==='select-case'){selected=data.caseId;}else{({investigate:()=>investigate(s),rehearse:()=>rehearse(s),approve:()=>approve(s,s.rehearsal?.id),repair:()=>{applyRepair(s);verify(s,{paymentAvailable:s.scenario!=='read-error'})},verify:()=>verify(s),pay:()=>simulatePayment(s)})[action]?.();save();}consent=false;}catch(e){error=e.message;consent=false;syncRequired=backend;}finally{busy=false;render();}}
async function init(){busy=true;error='';render();try{if(backend){await api('state');await refresh();}else{try{const saved=JSON.parse(sessionStorage.getItem(storageKey));if(Array.isArray(saved)&&saved.length&&saved.every(s=>s.schema===1&&s.order&&s.events))cases=saved;}catch{}if(!cases.length){const first=simulatePayment(createCase());cases=seedPortfolio(first);for(const s of cases.slice(0,3))investigate(s);const retry=simulatePayment(createCase('read-error','CL-1056'));retry.customerName='Robin';investigate(retry);cases.push(retry);save();}}loaded=true;}catch(e){error=e.message;}finally{busy=false;render();}}
await init();
mountNewCase({backend,api,isBusy:()=>busy||!loaded,onCreated:async state=>{merge(validateCase(state));screen='cases';consent=false;error='';syncRequired=false;save();render();notify('Case created. Review the payment source before continuing.');}});
